C13 = [
("s4","Wat is een kristalontvanger?","De eenvoudigste ontvanger: een antenne, een afgestemde kring, een diode als AM-detector en een koptelefoon. Geen voeding of versterker nodig."),
("s4","Hoe werkt de omhullende-detector?","Een diode laat één fasehelft door; een condensator (met belasting) volgt de toppen: de omhullende, dus het LF-signaal."),
("s4","Waarom zit er een dubbele afstemcondensator in een ontvanger?","Om twee kringen tegelijk af te stemmen (voor antenne en oscillator of HF-trap)."),
("s5","Wat is een rechtuitontvanger?","Een ontvanger met HF-versterking, detector en LF-versterker. De selectiviteit moet in de HF-trap zitten en is bij hoge frequenties beperkt."),
("s6","Wat is een regeneratieve ontvanger?","Een detector met positieve terugkoppeling: de versterking en selectiviteit nemen sterk toe tot vlak voor het oscilleren."),
("s7","Wat is een superheterodyne-ontvanger?","Een ontvanger die het ontvangen signaal omzet naar een vaste middenfrequentie (MF), waarop selectiviteit en versterking plaatsvinden."),
("s7","Welke trappen heeft een superheterodyne-ontvanger?","HF-trap, mengtrap met oscillator, MF-versterker met filter, detector, LF-versterker en AVR."),
("s7","Wat doet de mengtrap?","Mengt het ontvangen signaal met het oscillatorsignaal en levert onder meer het verschil: de middenfrequentie."),
("s7","Hoe bereken je de middenfrequentie?","MF = |foscillator − fontvangst|."),
("s7","Wat is de spiegelfrequentie?","De ongewenste frequentie die ook op de MF uitkomt: aan de andere kant van de oscillatorfrequentie. Ze ligt 2 × MF van de ontvangfrequentie."),
("s7","Hoe onderdruk je de spiegelfrequentie?","Met een selectieve HF-trap (voorselectie) of een hogere MF, of met een dubbelsuper."),
("s7","Wat is een dubbelsuper?","Een superheterodyne-ontvanger met twee menging en twee middenfrequenties: een hoge eerste MF (spiegelonderdrukking) en een lage tweede MF (selectiviteit)."),
("s7","Wat doet de HF-trap in een ontvanger?","Versterkt zwakke signalen (met weinig ruis), onderdrukt spiegelfrequenties en andere ongewenste signalen (veraf-selectiviteit) en verbetert de gevoeligheid."),
("s7","Wat bepaalt de nabij-selectiviteit?","De filters in de MF-trap(pen)."),
("s7","Wat is veraf-selectiviteit?","De onderdrukking van signalen ver van de ontvangfrequentie, vooral de spiegelfrequentie; vooral bepaald door de HF-trap."),
("s7","Wat is de AVR/AGC?","Automatische versterkingsregeling: regelt de versterking van de HF- en MF-trappen terug bij een sterk signaal, zodat het uitgangsniveau gelijk blijft."),
("s7","Welke trap in een ontvanger levert de meeste ruis?","De eerste trap (HF-trap of mengtrap): daar is het signaal het zwakst."),
("s7","Waarom een lage ruis-HF-trap?","Een goed ruisgetal van de eerste trap bepaalt de gevoeligheid van de hele ontvanger."),
("s7","Waarom heeft een ontvanger een HF-trap vóór de mengtrap?","Om ruis en spiegelonderdrukking te verbeteren."),
("s8","Welke filters gebruikt men in de MF?","Bandfilters, kristalfilters, keramische en mechanische filters."),
("s8","Wat is een bandfilter?","Twee gekoppelde kringen: bij kritische koppeling een vlakke top, onderkritisch smal, overkritisch met twee toppen en breder."),
("s8","Wat gebeurt bij overkritische koppeling van een bandfilter?","De doorlaatkromme krijgt twee toppen (met een dal ertussen) en wordt breder."),
("s8","Wat gebeurt bij onderkritische koppeling?","De secundaire spanning is lager en de kromme is smaller dan bij kritische koppeling."),
("s9","Wat zijn ongewenste mengproducten in een dubbelsuper?","Menging met de oscillators geeft ook ongewenste frequenties (zoals spiegelfrequenties van de tweede menging)."),
("s10","Wat is selectiviteit?","De mate waarin ongewenste frequenties worden onderdrukt ten opzichte van de frequentie waarop de ontvanger is ingesteld."),
("s10","Wat is gevoeligheid?","Het vermogen (of de spanning) aan de ingang dat nodig is voor een verstaanbaar signaal aan de uitgang."),
("s10","Waar hangt de gevoeligheid vooral van af?","Van de signaal/ruisverhouding (S/N), dus vooral van de eerste trap, niet van de mate van versterking."),
("s10","Wat is signaal/ruisverhouding?","SNR = Psignaal / Pruis (vaak in dB)."),
("s10","Helpt meer versterken tegen ruis?","Nee: signaal en ruis worden even sterk versterkt, de verhouding verandert niet."),
("s10","Hoe ontstaat ruis?","Door trillende deeltjes in geleiders boven het absolute nulpunt; hoe hoger de temperatuur, hoe meer ruis."),
("s10","Wat is het ruisgetal F?","F = (Sin/Nin) / (Suit/Nuit); een ideale ontvanger heeft F = 1 (0 dB). In dB: SNR in − SNR uit."),
("s10","Wat is reciproke menging?","Faseruis van de oscillator mengt een sterk signaal naast het gewenste signaal toch naar de MF-doorlaat."),
("s10","Wat is nodig voor weinig reciproke menging?","Een oscillator met weinig faseruis."),
("s10","Waarom een HF-verzwakker aan de ingang?","Om intermodulatie en kruismodulatie door sterke signalen tegen te gaan; de signaal/ruisverhouding verandert nauwelijks."),
("s10","Wat bepaalt de bandbreedte van een kring met Q?","B = f / Q (−3 dB-punten)."),
("s12","Hoe werkt een AM-detector?","Een diode met een RC-netwerk (omhullende-detector): gelijkrichten en afvlakken van de HF."),
("s13","Hoe detecteer je DZB?","Met een productdetector en een oscillator met de frequentie van de (onderdrukte) draaggolf."),
("s14","Hoe detecteer je EZB?","Met een productdetector (mengtrap) en een BFO met de frequentie van de draaggolf, die bij de ontvangst wordt teruggebracht."),
("s14","Waarom heeft EZB een BFO nodig?","De draaggolf is onderdrukt en moet in de ontvanger worden toegevoegd, anders is het signaal onverstaanbaar."),
("s14","Wat gebeurt als de BFO-frequentie niet klopt bij EZB?","De stem klinkt te hoog of te laag (Donald Duck) of onverstaanbaar."),
("s15","Wat gebeurt als je de BFO aan de andere kant van de MF zet?","USB wordt LSB (en omgekeerd): het zijbandspectrum wordt gespiegeld."),
("s16","Hoe maak je CW hoorbaar?","Met een BFO of zwevingsoscillator die een paar honderd Hz van de MF afligt; het verschil is een toon."),
("s16","Op welke frequentie staat de BFO voor CW?","MF ± gewenste toon (bijvoorbeeld 456 kHz bij 455 kHz MF en 1 kHz toon)."),
("s17","Wat is een directe-conversieontvanger?","Een ontvanger zonder MF: de oscillator staat op de ontvangfrequentie en de mengtrap levert direct het LF-signaal (nul-MF)."),
("s17","Wat is een nadeel van directe conversie?","Dubbele zijbanden (beide zijbanden worden ontvangen) en gevoeligheid voor brom en LF-ruis."),
("s18","Hoe detecteer je FM?","Met een FM-detector (discriminator): de frequentieafwijking wordt omgezet in een spanning. Voorbeelden: Foster-Seeley, ratiodetector, PLL en flankdetectie."),
("s18","Wat is flankdetectie?","Een kring wordt iets naast de draaggolf afgestemd; de frequentieafwijking verandert de amplitude, en die wordt met een AM-detector omgezet. Een bijzondere toepassing van een AM-detector."),
("s18","Wat doet de begrenzer in een FM-ontvanger?","Hij begrenst de amplitude van het MF-signaal, zodat amplitudevariaties (ruis en storing) wegvallen."),
("s18","Wat is een squelch?","Een ruisonderdrukker: de LF-versterker wordt gedempt als er geen signaal is (alleen ruis), zodat je geen ruis hoort."),
("s18","Waarop reageert een squelch-schakeling?","Op de ruis in het LF-signaal (of de ruis boven de spraakfrequenties): bij veel ruis wordt de LF-trap afgesloten."),
("s18","Waarom heeft FM de hoogste MF-bandbreedte?","De bandbreedte van FM is minstens 3× zo groot als van AM en EZB (regel van Carson)."),
("s19","Wat is een transceiver?","Een zender en ontvanger in één apparaat, die vaak oscillatoren en filters delen."),
("s20","Wat meet de S-meter?","De signaalsterkte aan de ingang, aangestuurd door de AVR-spanning, logaritmisch."),
("s20","Hoeveel dB is een S-punt?","6 dB: spanning twee keer zo groot en vermogen vier keer zo groot."),
("s20","Hoeveel is S9 op HF en op VHF/UHF?","HF: 50 µV aan 50 Ω; VHF/UHF (boven 30 MHz): 5 µV."),
("s20","Wat is S9 + 20 dB?","20 dB boven S9: spanning 10 keer en vermogen 100 keer zo groot."),
("s20","Wat gebeurt er met de S-meter als een zender zijn vermogen 4 keer zo laag maakt?","De aanwijzing daalt 6 dB, dus een S-punt."),
("s22","Wat is een PLL?","Phase Locked Loop: een regellus die de frequentie van een oscillator vergrendelt op een referentie."),
("s23","Welke onderdelen heeft een PLL?","Fasevergelijker (fasedetector), lusfilter (laagdoorlaat), VCO en eventueel een deler in de terugkoppeling."),
("s23","Wat doet de fasevergelijker?","Vergelijkt de fase van de referentie en de VCO en levert een foutspanning evenredig met het faseverschil."),
("s23","Wat is de toestand 'gelocked'?","De VCO heeft precies de frequentie van de referentie (of een veelvoud via deler) en een vast faseverschil; de foutspanning is stabiel."),
("s24","Wat is een VCO?","Voltage Controlled Oscillator: de frequentie wordt bepaald door een stuurspanning, bijvoorbeeld via een varicap."),
("s24","Waarvoor dient een varicap?","Een capaciteitsdiode waarvan de capaciteit met de sperspanning verandert: afstemmen of moduleren van een oscillator."),
("s25","Hoe werkt een PLL als FM-detector?","De VCO volgt de frequentie van het FM-signaal; de stuurspanning van de VCO is het LF-signaal."),
("s26","Hoe werkt een frequentiesynthesizer met PLL?","Een deler tussen VCO en fasevergelijker: bij lock geldt fVCO = N × fref, met rasterstappen gelijk aan fref."),
("s26","Hoe stel je de uitgangsfrequentie van een PLL-synthesizer in?","Door de deelfactor N te veranderen; de stap is gelijk aan de referentiefrequentie."),
("s27","Hoe maak je FM met een PLL?","Door de LF-modulatie op de VCO te zetten, terwijl de lus de gemiddelde frequentie stabiel houdt."),
("s29","Wat is DSP?","Digital Signal Processing: een signaal wordt gedigitaliseerd (ADC), digitaal bewerkt en eventueel weer omgezet naar analoog (DAC)."),
("s29","In welke volgorde staan ADC, DSP en DAC?","Analoog in → ADC → digitale verwerking → DAC → analoog uit."),
("s30","Wat is bemonstering?","Het met regelmatige tussenpozen meten van de momentele waarde van een analoog signaal."),
("s32","Wat zegt de regel van Nyquist-Shannon?","De bemonsteringsfrequentie moet minstens 2× de hoogste frequentie in het signaal zijn."),
("s32","Wat is aliasing?","Een bemonsteringsfrequentie lager dan 2× de hoogste frequentie geeft een ander (alias) signaal met een lagere frequentie."),
("s32","Welke bemonsteringsfrequentie voor spraak tot 3 kHz?","Minstens 6 kHz, in de praktijk iets meer (bijvoorbeeld 8 kHz)."),
("s34","Wat doet een anti-aliasfilter?","Een laagdoorlaatfilter vóór de ADC dat frequenties boven de halve bemonsteringsfrequentie verwijdert."),
("s35","Wat is een ADC?","Analoog-digitaalomzetter: zet een spanning om naar een binair getal."),
("s35","Wat bepaalt de resolutie van een ADC?","Het aantal bits: n bits geeft 2ⁿ niveaus. 8 bits: 256 niveaus; 16 bits: 65536 niveaus."),
("s35","Wat is kwantiseringsruis?","Ruis door het afronden van de analoge waarde op de dichtstbijzijnde digitale waarde; kleiner bij meer bits."),
("s35","Hoeveel dB dynamisch bereik per bit?","Ongeveer 6 dB per bit: 16 bits is circa 96 dB."),
("s36","Wat zijn FIR en IIR?","Digitale filters: Finite Impulse Response (zonder terugkoppeling) en Infinite Impulse Response (met terugkoppeling)."),
("s37","Wat doet de Fouriertransformatie?","Zet een signaal om van het tijddomein naar het frequentiedomein (en omgekeerd)."),
("s38","Wat is DDS?","Direct Digital Synthesis: een digitale signaalgenerator die een sinus opwekt uit opgeslagen waarden (tabel + DAC), met zeer fijne frequentiestappen."),
("s38","Wat is de uitvoer van een DDS?","Via een DAC een analoog signaal, gevolgd door een reconstructiefilter (laagdoorlaat) om de bemonsteringsresten te verwijderen."),
("s39","Waarvoor dient een reconstructiefilter?","Een laagdoorlaatfilter na de DAC dat de stapjes in het signaal gladstrijkt."),
]

